INSERT INTO grammar_lessons (id, cefr_level, topic, topic_tr, content, content_tr) VALUES ('a1-telling-time', 'A1', 'Telling Time (Mis kell on?)', 'Saat Söyleme (Mis kell on?)', 'Telling Time in Estonian\n\nFull hours: Kell on uks. (1 o''''clock)\nHalf hours (pool = half BEFORE next hour):\n6:30 = pool seitse, 12:30 = pool uks\nQuarter past: 1:15 = veerand kaks\nQuarter to: 1:45 = kolmveerand kaks\n\nEstonian counts toward the NEXT hour!', 'Estoncada Saat Soyleme\n\nTam saatler: Kell on uks. (Saat 1)\nBucuklar (pool = sonraki saatin yarisi):\n6:30 = pool seitse, 12:30 = pool uks\nCeyrek gece: 1:15 = veerand kaks\nCeyrek kala: 1:45 = kolmveerand kaks\n\nEstonca sonraki saate gore sayar!') ON CONFLICT (id) DO NOTHING;
INSERT INTO grammar_lessons (id, cefr_level, topic, topic_tr, content, content_tr) VALUES ('a1-clothing-locations', 'A1', 'Clothing Grammar (Where is it worn?)', 'Kiyafet Grameri (Nereye giyilir?)', 'Where Clothing is Worn\n\npeas (on head): muts, kiiver\nkaelas (around neck): sall, lips\nseljas (on torso): sark, kampsun, jope\njalas (on legs/feet): puksid, saapad\nkaes (in hands): kindad, vihmavari\nees (on face): prillid, mask\n\nTal on muts peas. Tal on jope seljas.', 'Kiyafetler Nereye Giyilir?\n\npeas (basta): muts, kiiver\nkaelas (boyunda): sall, lips\nseljas (sirtta): sark, kampsun, jope\njalas (bacaklarda): puksid, saapad\nkaes (ellerde): kindad, vihmavari\nees (yuzde): prillid, mask\n\nTal on muts peas. Tal on jope seljas.') ON CONFLICT (id) DO NOTHING;
INSERT INTO grammar_lessons (id, cefr_level, topic, topic_tr, content, content_tr) VALUES ('a1-comitative-abessive', 'A1', 'With (-ga) and Without (-ta)', 'Ile (-ga) ve Siz (-ta)', '-ga (with): add to genitive form\nauto -> autoga, piim -> piimaga, sina -> sinuga\nMa joon kohvi piimaga. Ma soidan autoga.\n\n-ta (without): add to genitive form\nauto -> autota, suhkur -> suhkruta\nKohv suhkruta, palun. Ma olen ilma autota.', '-ga (ile): tamlayan haline eklenir\nauto -> autoga, piim -> piimaga, sina -> sinuga\nMa joon kohvi piimaga. Ma soidan autoga.\n\n-ta (siz): tamlayan haline eklenir\nauto -> autota, suhkur -> suhkruta\nKohv suhkruta, palun. Ma olen ilma autota.') ON CONFLICT (id) DO NOTHING;
INSERT INTO grammar_lessons (id, cefr_level, topic, topic_tr, content, content_tr) VALUES ('a1-ma-da-infinitive', 'A1', 'MA vs DA Infinitive', 'MA ve DA Mastar Sistemi', 'MA-infinitive: after movement/obligation verbs\nMa lahen oppima. Ma hakkan tootama.\n\nDA-infinitive: after desire/feeling/ability verbs\nMa tahan oppida. Mulle meeldib tantsida. Ma oskan ujuda.\n\nPairs: jooma/juua, sooma/suua, oppima/oppida, minema/minna', 'MA-mastar: hareket/zorunluluk fiillerinden sonra\nMa lahen oppima. Ma hakkan tootama.\n\nDA-mastar: istek/duygu/yetenek fiillerinden sonra\nMa tahan oppida. Mulle meeldib tantsida. Ma oskan ujuda.\n\nCiftler: jooma/juua, sooma/suua, oppima/oppida, minema/minna') ON CONFLICT (id) DO NOTHING;
